export const cargoOfficerRows=()=>structuredClone(rows);
export function cargoOfficerRow(id){return structuredClone(rows.find(r=>r.pointId===id)??null)}
export function cargoOfficerBodyClear(scene,p){if(!Array.isArray(p)||p.length!==2||!p.every(Number.isInteger))return false;return rows.filter(r=>r.sceneId===scene).every(r=>{const[l,t,x,b]=r.playerForbiddenHalfOpen;return p[0]<l||p[0]>=x||p[1]<t||p[1]>=b})}
export function inCargoOfficerFront(id,scene,p,facing){const r=rows.find(r=>r.pointId===id);return !!r&&r.sceneId===scene&&facing===r.facing&&cargoOfficerBodyClear(scene,p)&&r.runsHalfOpen.some(([y,a,b])=>p[1]===y&&p[0]>=a&&p[0]<b)}
